        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeAttachmentListener.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface AttachmentListener: handle missing in uniffiClone")
