    fileprivate static let handleMap = UniffiHandleMap<EventObserver>()

    typealias FfiType = UInt64
    typealias SwiftType = EventObserver

    public static func lift(_ handle: UInt64) throws -> EventObserver {
        if ((handle & 1) == 0) {
