// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * FFI copy of [`EngineEvent`]. `loser_value` stays JSON because `UniFFI` has no
 * `serde_json::Value`.
 */

public enum FfiEngineEvent: Equatable, Hashable {
    
    case localChanged
    case mutationRejected(mutationId: String, reason: String
    )
    case queueDepth(depth: UInt32
    )
    case resetRequired
    case checkpointExpired
    case batchAborted(offenderMutationId: String, reason: String
    )
    case deadLetter(mutationId: String, reason: String
    )
    case columnOverwritten(table: String, pk: String, column: String, loserValueJson: String, winnerMutationId: String, conflictMode: String
    )





}

#if compiler(>=6)
extension FfiEngineEvent: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiEngineEvent: FfiConverterRustBuffer {
    typealias SwiftType = FfiEngineEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiEngineEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .localChanged
        
        case 2: return .mutationRejected(mutationId: try FfiConverterString.read(from: &buf), reason: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .queueDepth(depth: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 4: return .resetRequired
        
        case 5: return .checkpointExpired
        
        case 6: return .batchAborted(offenderMutationId: try FfiConverterString.read(from: &buf), reason: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .deadLetter(mutationId: try FfiConverterString.read(from: &buf), reason: try FfiConverterString.read(from: &buf)
        )
        
        case 8: return .columnOverwritten(table: try FfiConverterString.read(from: &buf), pk: try FfiConverterString.read(from: &buf), column: try FfiConverterString.read(from: &buf), loserValueJson: try FfiConverterString.read(from: &buf), winnerMutationId: try FfiConverterString.read(from: &buf), conflictMode: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiEngineEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case .localChanged:
            writeInt(&buf, Int32(1))
        
        
        case let .mutationRejected(mutationId,reason):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(mutationId, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .queueDepth(depth):
            writeInt(&buf, Int32(3))
            FfiConverterUInt32.write(depth, into: &buf)
            
        
        case .resetRequired:
            writeInt(&buf, Int32(4))
        
        
        case .checkpointExpired:
            writeInt(&buf, Int32(5))
        
        
        case let .batchAborted(offenderMutationId,reason):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(offenderMutationId, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .deadLetter(mutationId,reason):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(mutationId, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .columnOverwritten(table,pk,column,loserValueJson,winnerMutationId,conflictMode):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(table, into: &buf)
            FfiConverterString.write(pk, into: &buf)
            FfiConverterString.write(column, into: &buf)
            FfiConverterString.write(loserValueJson, into: &buf)
            FfiConverterString.write(winnerMutationId, into: &buf)
            FfiConverterString.write(conflictMode, into: &buf)
            
        }
    }
}


